<div class="grid gap-4 md:grid-cols-2 lg:grid-cols-3"><div><label>Name *</label><input class="w-full" name="name" required @if(isset($editing)) x-model="edit.name" @endif></div><div><label>Phone</label><input class="w-full" name="mobile" @if(isset($editing)) x-model="edit.mobile" @endif></div><div><label>WhatsApp</label><input class="w-full" name="whatsapp" @if(isset($editing)) x-model="edit.whatsapp" @endif></div><div><label>Email</label><input class="w-full" type="email" name="email" @if(isset($editing)) x-model="edit.email" @endif></div><div><label>Credit limit</label><input class="w-full" type="number" step="0.01" name="credit_limit" value="0" @if(isset($editing)) x-model="edit.credit_limit" @endif></div><div><label>Opening balance</label><input class="w-full" type="number" step="0.01" name="opening_balance" value="0" @if(isset($editing)) x-model="edit.opening_balance" @endif></div><div class="md:col-span-2"><label>Address</label><input class="w-full" name="address" @if(isset($editing)) x-model="edit.address" @endif></div><div><label>Notes</label><input class="w-full" name="notes" @if(isset($editing)) x-model="edit.notes" @endif></div></div>
